import { Question } from './types';

export const questions: Question[] = [
  // ABACAXI
  { id: 1, culture: 'Abacaxi', topic: 'Fisiologia (Metabolismo CAM)', text: 'O abacaxizeiro realiza fotossíntese pelo metabolismo CAM, com os estômatos abertos à noite e fechados durante o dia.', answer: 'V', explanation: 'Característica central do metabolismo CAM.' },
  { id: 2, culture: 'Abacaxi', topic: 'Fisiologia (Metabolismo CAM)', text: 'À noite, o CO₂ é fixado pela enzima Rubisco, formando ácido málico armazenado no vacúolo das células.', answer: 'F', explanation: 'À noite, quem fixa o CO₂ é a PEPcase (formando ácido málico); a Rubisco atua de dia.' },
  { id: 3, culture: 'Abacaxi', topic: 'Fisiologia (Metabolismo CAM)', text: 'Durante o dia, com os estômatos fechados, o malato acumulado é descarboxilado, e o CO₂ liberado internamente é fixado pela Rubisco no Ciclo de Calvin.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 4, culture: 'Abacaxi', topic: 'Fisiologia (Metabolismo CAM)', text: 'O metabolismo CAM confere ao abacaxizeiro uma taxa de crescimento mais rápida do que a de plantas C3 ou C4, em razão de sua alta eficiência energética.', answer: 'F', explanation: 'É o contrário: o CAM tem crescimento mais lento — a planta troca velocidade de crescimento por eficiência no uso da água.' },
  { id: 5, culture: 'Abacaxi', topic: 'Fisiologia (Metabolismo CAM)', text: 'A baixa densidade estomática do abacaxizeiro (cerca de 70 a 80 estômatos/mm²) é uma característica xeromórfica que complementa o metabolismo CAM.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 6, culture: 'Abacaxi', topic: 'Botânica e Morfologia', text: 'A folha D é a folha mais velha da planta, sendo usada como referência para o diagnóstico nutricional e para avaliar a prontidão para a indução floral.', answer: 'F', explanation: 'A folha D é a folha mais nova já fisiologicamente ativa, não a mais velha.' },
  { id: 7, culture: 'Abacaxi', topic: 'Botânica e Morfologia', text: 'O fruto do abacaxi é tecnicamente chamado de sorose, resultante da fusão de vários frutilhos originados de flores dispostas em espiral.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 8, culture: 'Abacaxi', topic: 'Botânica e Morfologia', text: 'A formação do fruto do abacaxi depende de fecundação cruzada entre plantas geneticamente diferentes.', answer: 'F', explanation: 'O fruto se forma por partenocarpia, sem necessidade de fecundação.' },
  { id: 9, culture: 'Abacaxi', topic: 'Botânica e Morfologia', text: 'Em ordem decrescente de vigor, temos: rebentão > filhote-rebentão > filhote > coroa.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 10, culture: 'Abacaxi', topic: 'Botânica e Morfologia', text: 'Em ordem decrescente de uniformidade entre plantas de uma mesma área, temos: rebentão > filhote > coroa.', answer: 'F', explanation: 'É o oposto: coroa > filhote > filhote-rebentão > rebentão — o rebentão é o mais vigoroso, mas o menos uniforme.' },
  { id: 11, culture: 'Abacaxi', topic: 'Clima, Ciclo de Vida e Propagação', text: 'A floração natural do abacaxizeiro é estimulada por dias curtos associados a temperaturas noturnas mais baixas (próximas de 22°C), desde que a planta já tenha completado a fase vegetativa.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 12, culture: 'Abacaxi', topic: 'Clima, Ciclo de Vida e Propagação', text: 'A fase vegetativa do abacaxizeiro dura, em média, de 8 a 12 meses.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 13, culture: 'Abacaxi', topic: 'Clima, Ciclo de Vida e Propagação', text: 'A fase reprodutiva (da indução floral até a colheita) costuma ser mais longa no segundo semestre do que no primeiro, por causa das temperaturas mais baixas nesse período.', answer: 'F', explanation: 'É o contrário: a fase reprodutiva é mais longa no 1º semestre (temperaturas mais amenas) e mais curta no 2º semestre (mais calor).' },
  { id: 14, culture: 'Abacaxi', topic: 'Clima, Ciclo de Vida e Propagação', text: 'O rebentão, por surgir mais cedo que o filhote, confere maior uniformidade entre as plantas de um mesmo talhão.', answer: 'F', explanation: 'O rebentão é o mais vigoroso, mas confere menor uniformidade (cada planta o emite em seu próprio tempo); é o filhote que confere maior uniformidade, por surgir após um evento comum (a indução floral).' },
  { id: 15, culture: 'Abacaxi', topic: 'Clima, Ciclo de Vida e Propagação', text: 'A soca (segundo ciclo produtivo do abacaxizeiro) é explorada a partir do rebentão, sem necessidade de replantio.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 16, culture: 'Abacaxi', topic: 'Indução Floral, Pragas e Doenças', text: 'O carbureto de cálcio, ao reagir com água, libera gás acetileno, que tem efeito semelhante ao etileno na indução floral do abacaxizeiro.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 17, culture: 'Abacaxi', topic: 'Indução Floral, Pragas e Doenças', text: 'A aplicação de etefom ou carbureto de cálcio para indução floral deve ser feita preferencialmente durante o dia, quando os estômatos estão mais abertos.', answer: 'F', explanation: 'Deve ser feita à noite (20h-5h), justamente quando os estômatos estão abertos no metabolismo CAM.' },
  { id: 18, culture: 'Abacaxi', topic: 'Indução Floral, Pragas e Doenças', text: 'A avaliação da eficiência da indução floral é feita entre 45 e 60 dias após o tratamento, considerando-se satisfatório um índice de resposta igual ou superior a 90%.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 19, culture: 'Abacaxi', topic: 'Indução Floral, Pragas e Doenças', text: 'A fusariose do abacaxizeiro, causada por Fusarium guttiforme, é disseminada principalmente por meio de mudas contaminadas.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 20, culture: 'Abacaxi', topic: 'Indução Floral, Pragas e Doenças', text: 'A broca-do-fruto do abacaxizeiro realiza postura preferencialmente em frutos já maduros, próximos à colheita.', answer: 'F', explanation: 'A postura ocorre exclusivamente em flores abertas, não em frutos maduros.' },
  { id: 21, culture: 'Abacaxi', topic: 'Colheita e Pós-Colheita', text: 'O abacaxi é um fruto climatérico, continuando a amadurecer após a colheita.', answer: 'F', explanation: 'O abacaxi é não climatérico — não evolui mais após a colheita.' },
  { id: 22, culture: 'Abacaxi', topic: 'Colheita e Pós-Colheita', text: 'O padrão mínimo de sólidos solúveis totais geralmente exigido para a colheita comercial do abacaxi é de 12 °Brix.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 23, culture: 'Abacaxi', topic: 'Colheita e Pós-Colheita', text: 'O escurecimento interno (chilling injury) do abacaxi em pós-colheita é causado pela ação das enzimas polifenoloxidase e peroxidase sobre compostos fenólicos, após dano por frio prolongado.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 24, culture: 'Abacaxi', topic: 'Colheita e Pós-Colheita', text: 'O ácido ascórbico e o potássio são fatores que aumentam o risco de escurecimento interno do abacaxi.', answer: 'F', explanation: 'É o contrário: reduzem o risco — o ácido ascórbico inibe a polifenoloxidase, e o potássio eleva o teor de ácido ascórbico do fruto.' },
  { id: 25, culture: 'Abacaxi', topic: 'Colheita e Pós-Colheita', text: 'O abacaxi não deve ser transportado ou armazenado junto com a banana, por causa da incompatibilidade nas condições ideais de conservação.', answer: 'V', explanation: 'Afirmação correta.' },

  // MARACUJÁ
  { id: 26, culture: 'Maracujá', topic: 'Botânica e Biologia Floral', text: 'A flor do maracujazeiro é pentâmera e possui apenas um estigma, diferente da maioria das plantas.', answer: 'F', explanation: 'A flor do maracujá possui 3 estigmas, não apenas um.' },
  { id: 27, culture: 'Maracujá', topic: 'Botânica e Biologia Floral', text: 'A corona do maracujazeiro protege a região onde se acumula o néctar, na base da flor.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 28, culture: 'Maracujá', topic: 'Botânica e Biologia Floral', text: 'O maracujá-amarelo é autoincompatível, não podendo ser fecundado pelo próprio pólen nem pelo de plantas muito aparentadas.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 29, culture: 'Maracujá', topic: 'Botânica e Biologia Floral', text: 'A antese do maracujá-amarelo tem início por volta do meio-dia/13h e dura aproximadamente uma hora.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 30, culture: 'Maracujá', topic: 'Botânica e Biologia Floral', text: 'Cerca de 71% das flores abertas de maracujá atingem curvatura total dos estiletes, sendo essa a categoria estéril.', answer: 'F', explanation: 'A curvatura total (~71%) é a categoria viável, com melhor chance de fecundação; a categoria estéril é a "sem curvatura" (~6%).' },
  { id: 31, culture: 'Maracujá', topic: 'Polinização', text: 'A mamangava (gênero Xylocopa) é considerada o polinizador mais eficiente do maracujazeiro.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 32, culture: 'Maracujá', topic: 'Polinização', text: 'A abelha arapuá (Trigona spinipes) é uma polinizadora eficiente do maracujá, contribuindo para aumentar a produtividade do pomar.', answer: 'F', explanation: 'A arapuá é ineficiente como polinizadora e é considerada uma praga — rouba néctar sem tocar os órgãos reprodutivos e ainda afugenta as mamangavas.' },
  { id: 33, culture: 'Maracujá', topic: 'Polinização', text: 'A polinização artificial do maracujazeiro é capaz de elevar o vingamento de frutos de cerca de 35-40% (natural) para 85-95%.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 34, culture: 'Maracujá', topic: 'Polinização', text: 'O grão de pólen do maracujá é leve e seco, sendo disseminado principalmente pelo vento.', answer: 'F', explanation: 'O grão de pólen é pesado e viscoso; a polinização pelo vento é praticamente inexistente.' },
  { id: 35, culture: 'Maracujá', topic: 'Polinização', text: 'A reação de incompatibilidade genética no maracujá forma uma calosidade no ponto de deposição do pólen no estigma, impedindo o crescimento do tubo polínico.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 36, culture: 'Maracujá', topic: 'Clima, Solo, Propagação e Condução', text: 'O maracujazeiro exige um mínimo de 11 horas de luz por dia para a emissão de botões florais.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 37, culture: 'Maracujá', topic: 'Clima, Solo, Propagação e Condução', text: 'O maracujazeiro tolera bem o encharcamento prolongado do solo, sendo pouco suscetível a doenças radiculares nessas condições.', answer: 'F', explanation: 'É o contrário: o maracujazeiro é sensível ao encharcamento, que favorece fusariose e podridão do colo.' },
  { id: 38, culture: 'Maracujá', topic: 'Clima, Solo, Propagação e Condução', text: 'As linhas de plantio em espaldeira devem ser orientadas no sentido leste-oeste, para maximizar a exposição solar de um dos lados da fileira.', answer: 'F', explanation: 'Devem ser orientadas no sentido norte-sul, para que ambos os lados da fileira recebam luz ao longo do dia.' },
  { id: 39, culture: 'Maracujá', topic: 'Clima, Solo, Propagação e Condução', text: 'A latada (ou caramanchão), apesar de mais produtiva por área, dificulta a polinização artificial e a colheita, por deixar flores e frutos na parte alta da estrutura.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 40, culture: 'Maracujá', topic: 'Clima, Solo, Propagação e Condução', text: 'A gavinha do maracujazeiro deve ser retirada por meio de corte, nunca puxada, para não danificar o ramo.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 41, culture: 'Maracujá', topic: 'Nutrição e Doenças', text: 'A ordem de exigência de macronutrientes pelo maracujazeiro é: nitrogênio > potássio > cálcio > enxofre > fósforo > magnésio.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 42, culture: 'Maracujá', topic: 'Nutrição e Doenças', text: 'No maracujazeiro, assim como no abacaxizeiro, o potássio é o macronutriente mais exigido.', answer: 'F', explanation: 'No maracujá, o nitrogênio é o macronutriente mais exigido (N > K > Ca > S > P > Mg); no abacaxi é o potássio — atenção para não confundir as duas culturas!' },
  { id: 43, culture: 'Maracujá', topic: 'Nutrição e Doenças', text: 'A fusariose do maracujazeiro causa lesão em toda a circunferência do colo, com a casca se soltando facilmente do lenho e os vasos lenhosos com coloração vermelho-vinho ao corte.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 44, culture: 'Maracujá', topic: 'Nutrição e Doenças', text: 'A podridão do colo do maracujazeiro (Phytophthora), diferentemente da fusariose, costuma apresentar lesão restrita a apenas parte da circunferência do colo, com a casca aderida ao lenho.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 45, culture: 'Maracujá', topic: 'Nutrição e Doenças', text: 'O vírus do endurecimento dos frutos do maracujazeiro (PWV/CABMV) é transmitido principalmente por um ácaro do gênero Brevipalpus.', answer: 'F', explanation: 'É transmitido principalmente por pulgões (e mecanicamente); o ácaro Brevipalpus transmite outra virose, a pinta-verde/definhamento precoce.' },
  { id: 46, culture: 'Maracujá', topic: 'Colheita e Pós-Colheita', text: 'O maracujá é um fruto climatérico, continuando a evoluir seu processo de maturação após a colheita.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 47, culture: 'Maracujá', topic: 'Colheita e Pós-Colheita', text: 'Para a indústria de suco, o maracujá deve ser colhido ainda verde, diretamente do ramo, para garantir maior teor de sólidos solúveis.', answer: 'F', explanation: 'Para a indústria, o maracujá deve ser colhido completamente maduro (geralmente já caído no chão) — é para o mercado in natura que se colhe no ramo, com ~30% de casca amarela.' },
  { id: 48, culture: 'Maracujá', topic: 'Colheita e Pós-Colheita', text: 'O ponto de colheita do maracujá ocorre, em geral, entre 50 e 63 dias após a antese, com teor de sólidos solúveis em torno de 16 °Brix.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 49, culture: 'Maracujá', topic: 'Colheita e Pós-Colheita', text: 'A vida de prateleira do maracujá em temperatura ambiente é de várias semanas, semelhante à do abacaxi.', answer: 'F', explanation: 'A vida de prateleira do maracujá é muito curta — murcha em 1-2 dias em temperatura ambiente.' },
  { id: 50, culture: 'Maracujá', topic: 'Colheita e Pós-Colheita', text: 'A câmara fria para o maracujá, na faixa de 7°C a 10°C, pode retardar a maturação por cerca de 20 dias.', answer: 'V', explanation: 'Afirmação correta.' },

  // MAMÃO
  { id: 51, culture: 'Mamão', topic: 'Biologia Floral e Genética do Sexo', text: 'O mamoeiro apresenta três tipos básicos de planta quanto ao sexo: feminina, masculina e hermafrodita.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 52, culture: 'Mamão', topic: 'Biologia Floral e Genética do Sexo', text: 'A flor hermafrodita do subtipo "pentandra" é a mais desejável comercialmente, originando o fruto piriforme de casca lisa.', answer: 'F', explanation: 'A flor elongata é a desejável comercialmente; a pentandra origina o fruto pentândrico, deformado e sem valor comercial.' },
  { id: 53, culture: 'Mamão', topic: 'Biologia Floral e Genética do Sexo', text: 'A carpeloidia é uma anomalia floral e fisiológica induzida por baixas temperaturas e excesso de nitrogênio, gerando frutos deformados conhecidos como "cara-de-gato".', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 54, culture: 'Mamão', topic: 'Biologia Floral e Genética do Sexo', text: 'Na genética do sexo do mamoeiro, o genótipo M1M2 (heterozigoto duplo-dominante) é viável e origina plantas de sexo intermediário.', answer: 'F', explanation: 'Combinações de dois alelos dominantes entre si (M1M1, M1M2, M2M2) são letais — não geram plantas viáveis de sexo intermediário.' },
  { id: 55, culture: 'Mamão', topic: 'Biologia Floral e Genética do Sexo', text: 'O cruzamento entre duas plantas hermafroditas (M2m × M2m) gera, entre a progênie viável, a proporção de 2 hermafroditas para 1 feminina.', answer: 'V', explanation: '66,7% hermafroditas e 33,3% femininas, entre a progênie viável, já que a combinação M2M2 é letal.' },
  { id: 56, culture: 'Mamão', topic: 'Biologia Floral e Genética do Sexo', text: 'A esterilidade feminina no mamoeiro é uma resposta fisiológica ao frio intenso, ocorrendo predominantemente em temperaturas abaixo de 10°C.', answer: 'F', explanation: 'Ocorre por estresse de calor (temperaturas acima de 28°C) e/ou déficit hídrico, não por frio.' },
  { id: 57, culture: 'Mamão', topic: 'Cultivares', text: 'O grupo Solo (Havaí) caracteriza-se por frutos menores, voltados principalmente ao mercado de exportação e consumo individual, enquanto o grupo Formosa tem frutos maiores, voltados ao mercado interno.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 58, culture: 'Mamão', topic: 'Cultivares', text: 'As cultivares do grupo Formosa são tradicionalmente plantadas com 3 mudas por cova (para a sexagem), e o grupo Solo com apenas 1 muda por cova.', answer: 'F', explanation: 'É o contrário: o grupo Solo é que usa tradicionalmente 3 mudas/cova (para permitir a sexagem, mantendo só a hermafrodita); o Formosa, historicamente, usa 1 muda/cova (sementes híbridas importadas, mais caras).' },
  { id: 59, culture: 'Mamão', topic: 'Nutrição, Meleira e Deficiências', text: 'A deficiência de cálcio no mamoeiro pode causar exsudação de látex na casca dos frutos jovens, mas com a casca permanecendo lisa, sem deformação.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 60, culture: 'Mamão', topic: 'Nutrição, Meleira e Deficiências', text: 'A deficiência de boro no mamoeiro causa frutos deformados, com "encaroçamento" e exsudação de látex em pontos localizados da casca.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 61, culture: 'Mamão', topic: 'Nutrição, Meleira e Deficiências', text: 'A virose da meleira do mamoeiro causa exsudação de látex idêntica, em intensidade e características, à causada pela deficiência de cálcio, sendo praticamente impossível diferenciá-las no campo.', answer: 'F', explanation: 'A meleira causa exsudação muito mais intensa, generalizada e fluida que a deficiência de cálcio.' },
  { id: 62, culture: 'Mamão', topic: 'Nutrição, Meleira e Deficiências', text: 'A ordem de exigência de macronutrientes pelo mamoeiro é: potássio > nitrogênio > cálcio > magnésio > enxofre ≈ fósforo.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 63, culture: 'Mamão', topic: 'Nutrição, Meleira e Deficiências', text: 'A deficiência de magnésio no mamoeiro manifesta-se da mesma forma em folhas novas e em folhas velhas, sem distinção de sintomas.', answer: 'F', explanation: 'Há distinção clara: em folhas velhas, amarelo intenso com nervuras verdes (rendilhado); em folhas novas, clorose com bordas curvadas para cima.' },
  { id: 64, culture: 'Mamão', topic: 'Doenças, Nematoides e Pragas', text: 'A podridão-do-pé (gomose), causada por Phytophthora palmivora, desenvolve-se rapidamente em solos pesados, encharcados e mal drenados, podendo matar a planta em 2 a 4 dias em condições de alagamento severo.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 65, culture: 'Mamão', topic: 'Doenças, Nematoides e Pragas', text: 'A pinta-preta (varíola), causada por Asperisporium caricae, é a doença foliar mais comum do mamoeiro, também provocando lesões na casca dos frutos.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 66, culture: 'Mamão', topic: 'Doenças, Nematoides e Pragas', text: 'O nematoide reniforme (Rotylenchulus reniformis) causa galhas radiculares volumosas, sintoma característico e exclusivo dessa espécie no mamoeiro.', answer: 'F', explanation: 'A formação de galhas é característica do nematoide-das-galhas (Meloidogyne); o reniforme causa aspecto de "grãos de areia" aderidos à raiz, sem galhas típicas.' },
  { id: 67, culture: 'Mamão', topic: 'Doenças, Nematoides e Pragas', text: 'O ácaro-branco (Polyphagotarsonemus latus) é considerado a praga mais importante e destrutiva do mamoeiro no Brasil.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 68, culture: 'Mamão', topic: 'Doenças, Nematoides e Pragas', text: 'As pragas mandarová, lagarta-rosca, cochonilha e percevejo-verde, apesar de citadas na literatura de fitossanidade do mamoeiro, não representam risco real à cultura em nenhuma situação de campo.', answer: 'F', explanation: 'São pragas secundárias, mas podem causar danos relevantes em certas condições — não são irrelevantes.' },
  { id: 69, culture: 'Mamão', topic: 'Colheita, Pós-Colheita e Exportação', text: 'O mamão é um fruto climatérico, assim como o maracujá e a banana, e diferentemente do abacaxi.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 70, culture: 'Mamão', topic: 'Colheita, Pós-Colheita e Exportação', text: 'O tratamento hidrotérmico do mamão para exportação aos Estados Unidos é uma exigência do USDA, associada ao controle de moscas-das-frutas.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 71, culture: 'Mamão', topic: 'Colheita, Pós-Colheita e Exportação', text: 'Uma praga quarentenária A1, segundo a classificação fitossanitária internacional, é aquela já amplamente disseminada no país exportador, mas ainda sob controle oficial ativo.', answer: 'F', explanation: 'É o contrário: praga A1 é a exótica, ainda não presente no país/área; a que já está presente mas sob controle oficial ativo é a A2.' },
  { id: 72, culture: 'Mamão', topic: 'Colheita, Pós-Colheita e Exportação', text: 'O mamão do grupo Solo, para exportação, deve seguir uma escala de coloração da casca padronizada, associada a estágios específicos de maturação.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 73, culture: 'Mamão', topic: 'Colheita, Pós-Colheita e Exportação', text: 'O programa "Systems Approach", utilizado na exportação de mamão do Espírito Santo aos EUA, baseia-se apenas na aplicação de agrotóxicos, sem monitoramento por armadilhas.', answer: 'F', explanation: 'O Systems Approach envolve monitoramento com armadilhas (com limiares de ação definidos), além de outras medidas integradas — não é só aplicação de agrotóxico.' },
  { id: 74, culture: 'Mamão', topic: 'Colheita, Pós-Colheita e Exportação', text: 'A sexagem no cultivo do mamoeiro é realizada no início do florescimento (cerca de 3 a 4 meses), com o objetivo de deixar apenas a planta de flor hermafrodita por cova comercial.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 75, culture: 'Mamão', topic: 'Colheita, Pós-Colheita e Exportação', text: 'O desbaste de frutos no mamoeiro tem como objetivo eliminar frutos carpeloides e malformados, além de regular o número de frutos por planta.', answer: 'V', explanation: 'Afirmação correta.' },

  // MANGA
  { id: 76, culture: 'Manga', topic: 'Botânica, Fisiologia e Fenologia', text: 'A mangueira pertence à família Anacardiaceae e produz um fruto do tipo drupa.', answer: 'V', explanation: 'Anacardiaceae; drupa.' },
  { id: 77, culture: 'Manga', topic: 'Botânica, Fisiologia e Fenologia', text: 'A nervura central da folha da mangueira apresenta coloração arroxeada quando a folha está madura, e amarelada quando ainda está em crescimento.', answer: 'F', explanation: 'É o contrário: amarelada = madura; arroxeada = em crescimento.' },
  { id: 78, culture: 'Manga', topic: 'Botânica, Fisiologia e Fenologia', text: 'A inflorescência da mangueira é polígama, produzindo flores hermafroditas e masculinas na mesma panícula.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 79, culture: 'Manga', topic: 'Botânica, Fisiologia e Fenologia', text: 'Sob condições tropicais, o florescimento da mangueira ocorre em ramos com 4 a 18 meses de idade.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 80, culture: 'Manga', topic: 'Botânica, Fisiologia e Fenologia', text: 'A mangueira é considerada uma planta de alta eficiência de polinização, com mais de 80% dos estigmas efetivamente atingidos pelo grão de pólen.', answer: 'F', explanation: 'A mangueira é planta de baixa polinização; só cerca de 45% dos estigmas são atingidos pelo pólen.' },
  { id: 81, culture: 'Manga', topic: 'Botânica, Fisiologia e Fenologia', text: 'O crescimento do fruto da mangueira segue um padrão sigmoide, levando de 100 a 150 dias até a maturação fisiológica.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 82, culture: 'Manga', topic: 'Botânica, Fisiologia e Fenologia', text: 'A temperatura ótima para o crescimento e desenvolvimento da mangueira situa-se entre 24°C e 26°C.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 83, culture: 'Manga', topic: 'Botânica, Fisiologia e Fenologia', text: 'Áreas de alta umidade relativa do ar (acima de 80%) são as mais recomendadas para o cultivo comercial da manga, por reduzirem o risco de oídio.', answer: 'F', explanation: 'Áreas de baixa umidade (<60%) são preferíveis — alta umidade favorece antracnose e oídio.' },
  { id: 84, culture: 'Manga', topic: 'Cultivares, Propagação e Plantio', text: 'A cultivar Tommy Atkins ocupa cerca de 95% da área dos pomares comerciais no Vale do São Francisco.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 85, culture: 'Manga', topic: 'Cultivares, Propagação e Plantio', text: 'As cultivares Espada e Rosa são poliembriônicas e frequentemente utilizadas como porta-enxerto.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 86, culture: 'Manga', topic: 'Cultivares, Propagação e Plantio', text: 'A cultivar Haden apresenta baixa suscetibilidade à antracnose e ao colapso interno, sendo considerada a mais resistente entre as variedades de exportação.', answer: 'F', explanation: 'A Haden é suscetível à antracnose, à malformação floral e ao colapso interno.' },
  { id: 87, culture: 'Manga', topic: 'Cultivares, Propagação e Plantio', text: 'A garfagem de fenda cheia é o método de enxertia mais utilizado na produção de mudas de mangueira, por apresentar precocidade e altos índices de pegamento.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 88, culture: 'Manga', topic: 'Cultivares, Propagação e Plantio', text: 'A retirada do tegumento externo da semente de manga antes da semeadura reduz o índice de germinação para menos de 50%.', answer: 'F', explanation: 'A retirada do tegumento aumenta a germinação para 90-95%.' },
  { id: 89, culture: 'Manga', topic: 'Cultivares, Propagação e Plantio', text: 'A implantação de um pomar tecnificado de manga para exportação recomenda espaçamentos entrelinhas de 6 a 8 m.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 90, culture: 'Manga', topic: 'Manejo da Floração e Poda', text: 'O paclobutrazol (PBZ) atua estimulando a síntese de giberelinas, o que acelera o crescimento vegetativo da mangueira.', answer: 'F', explanation: 'O PBZ inibe a síntese de giberelinas (não estimula).' },
  { id: 91, culture: 'Manga', topic: 'Manejo da Floração e Poda', text: 'A exsudação de látex nas gemas terminais e a epinastia das folhas maduras próximas ao ápice são sintomas visuais de que a planta está produzindo etileno.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 92, culture: 'Manga', topic: 'Manejo da Floração e Poda', text: 'O etefom deve ser aplicado em dosagens entre 200 ppm e 300 ppm no manejo da floração da mangueira.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 93, culture: 'Manga', topic: 'Manejo da Floração e Poda', text: 'A poda de topo da mangueira deve manter a altura máxima da planta em torno de 90% do espaçamento entrelinhas.', answer: 'F', explanation: 'A poda de topo mantém a altura em torno de 55% do espaçamento (não 90%).' },
  { id: 94, culture: 'Manga', topic: 'Manejo da Floração e Poda', text: 'A eliminação da inflorescência da mangueira, no estádio de "chumbinho", deve ser feita cortando-se a panícula rente ao tronco, sem deixar nenhum resíduo do ramo floral.', answer: 'F', explanation: 'O corte deve ser feito a 5 cm do nó terminal, não rente ao tronco.' },
  { id: 95, culture: 'Manga', topic: 'Manejo da Floração e Poda', text: 'A poda de formação da mangueira é composta por 5 a 6 operações, com a primeira poda realizada a 60-80 cm do solo, com corte abaixo do nó.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 96, culture: 'Manga', topic: 'Irrigação e Nutrição', text: 'O coeficiente de cultura (Kc) médio anual da mangueira no Vale do São Francisco é de aproximadamente 0,91.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 97, culture: 'Manga', topic: 'Irrigação e Nutrição', text: 'O potássio é considerado o nutriente mais importante para a qualidade do fruto da manga, influenciando cor da casca, aroma, tamanho e °Brix.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 98, culture: 'Manga', topic: 'Irrigação e Nutrição', text: 'O cálcio é um nutriente de alta mobilidade na planta, sendo eficientemente absorvido por aplicações foliares.', answer: 'F', explanation: 'O cálcio é praticamente imóvel na planta; aplicação foliar tem baixa eficiência.' },
  { id: 99, culture: 'Manga', topic: 'Irrigação e Nutrição', text: 'A deficiência de boro na mangueira está associada à morte da gema terminal e à consequente perda de dominância apical.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 100, culture: 'Manga', topic: 'Irrigação e Nutrição', text: 'Doses excessivas de nitrogênio na mangueira reduzem o risco de colapso interno dos frutos.', answer: 'F', explanation: 'Excesso de N aumenta o risco de colapso interno.' },
  { id: 101, culture: 'Manga', topic: 'Doenças e Pragas', text: 'A antracnose da mangueira é favorecida por condições de alta umidade relativa (acima de 90%) e temperaturas próximas a 28°C.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 102, culture: 'Manga', topic: 'Doenças e Pragas', text: 'O oídio da mangueira é favorecido por condições de alta umidade relativa e ausência de vento.', answer: 'F', explanation: 'O oídio é favorecido por baixa umidade relativa (não alta) — e por vento, que dispersa o fungo.' },
  { id: 103, culture: 'Manga', topic: 'Doenças e Pragas', text: 'A seca-da-mangueira, causada por Ceratocystis fimbriata, possui fungicida sistêmico eficaz registrado no Brasil para o seu controle.', answer: 'F', explanation: 'Não há fungicida eficaz registrado; o controle depende de resistência genética.' },
  { id: 104, culture: 'Manga', topic: 'Doenças e Pragas', text: 'A malformação floral da mangueira, causada por Fusarium subglutinans, pode reduzir a produção de uma panícula afetada a zero, pois as flores se tornam estaminadas.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 105, culture: 'Manga', topic: 'Doenças e Pragas', text: 'O MAD (moscas por armadilha por dia) máximo exigido para a exportação de manga aos Estados Unidos é de 1.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 106, culture: 'Manga', topic: 'Colheita e Pós-Colheita', text: 'O ponto de colheita da manga, em geral, ocorre entre 110 e 120 dias após a floração.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 107, culture: 'Manga', topic: 'Colheita e Pós-Colheita', text: 'Para mercados distantes, a manga pode ser colhida com teor de sólidos solúveis totais de 7 a 8 °Brix.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 108, culture: 'Manga', topic: 'Colheita e Pós-Colheita', text: 'O tratamento hidrotérmico contra fungos, exigido para exportação à Europa e ao Canadá, consiste na imersão dos frutos a 46,1°C por 75 a 90 minutos.', answer: 'F', explanation: 'Esse é o tratamento contra mosca-das-frutas (EUA/Japão/Chile). O tratamento contra fungos (Europa/Canadá) é 52°C por 5 minutos.' },
  { id: 109, culture: 'Manga', topic: 'Colheita e Pós-Colheita', text: 'O corte do pedúnculo na colheita da manga deve ter, no mínimo, 3 cm, para evitar vazamento excessivo de látex.', answer: 'V', explanation: 'Afirmação correta.' },

  // BANANA
  { id: 110, culture: 'Banana', topic: 'Botânica, Fisiologia, Clima e Solo', text: 'A bananeira é uma planta lenhosa, com crescimento secundário verdadeiro, sendo corretamente classificada como uma árvore.', answer: 'F', explanation: 'É uma planta herbácea monocotiledônea, sem crescimento secundário — não é uma árvore.' },
  { id: 111, culture: 'Banana', topic: 'Botânica, Fisiologia, Clima e Solo', text: 'O rizoma é o caule verdadeiro da bananeira, subterrâneo, do qual saem as raízes e, na parte apical, as folhas e a inflorescência.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 112, culture: 'Banana', topic: 'Botânica, Fisiologia, Clima e Solo', text: 'O pseudocaule é formado pela união das bainhas foliares e não deve ser confundido com o caule verdadeiro da planta.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 113, culture: 'Banana', topic: 'Botânica, Fisiologia, Clima e Solo', text: 'O fruto da bananeira comercial se desenvolve por partenocarpia, dispensando a necessidade de fecundação.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 114, culture: 'Banana', topic: 'Botânica, Fisiologia, Clima e Solo', text: 'A bananeira realiza fotossíntese pelo metabolismo CAM, com estômatos abertos à noite, da mesma forma que o abacaxizeiro.', answer: 'F', explanation: 'A bananeira tem metabolismo C3, não CAM (CAM é o abacaxi).' },
  { id: 115, culture: 'Banana', topic: 'Botânica, Fisiologia, Clima e Solo', text: 'A bananeira é extremamente tolerante ao encharcamento do solo, podendo o lençol freático estar a menos de 0,5 m de profundidade sem prejuízo às raízes.', answer: 'F', explanation: 'É extremamente sensível a encharcamento; o lençol freático deve estar a mais de 1-1,8 m.' },
  { id: 116, culture: 'Banana', topic: 'Botânica, Fisiologia, Clima e Solo', text: 'A temperatura ideal para o cultivo da bananeira situa-se entre 26°C e 28°C.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 117, culture: 'Banana', topic: 'Variedades e Propagação', text: 'O grupo genômico AAB é o mais frequente entre as cultivares comerciais de banana no Brasil, incluindo os subgrupos Prata e Terra/Plantain.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 118, culture: 'Banana', topic: 'Variedades e Propagação', text: 'A cultivar Maçã é altamente suscetível à sigatoka negra, o que restringe seu cultivo em grandes áreas no Brasil.', answer: 'F', explanation: 'A Maçã é suscetível principalmente ao mal-do-Panamá, não à sigatoka negra.' },
  { id: 119, culture: 'Banana', topic: 'Variedades e Propagação', text: 'Os híbridos Pacovan Ken, Preciosa e Japira, desenvolvidos pela Embrapa, apresentam resistência à sigatoka amarela e à sigatoka negra.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 120, culture: 'Banana', topic: 'Variedades e Propagação', text: 'Na muda tipo "chifrão", a planta já apresenta a primeira folha normal, diferentemente do chifrinho e do chifre, que ainda têm folha em forma de lança.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 121, culture: 'Banana', topic: 'Variedades e Propagação', text: 'No fracionamento de rizoma, a gema ("olho") deve ser posicionada voltada para cima no momento do plantio no canteiro de ceva.', answer: 'F', explanation: 'A gema deve ficar voltada para baixo, não para cima.' },
  { id: 122, culture: 'Banana', topic: 'Manejo Cultural e Nutrição', text: 'O desbaste de rebentos na bananeira é realizado aos 4, 6 e 10 meses após o plantio, com o auxílio da ferramenta chamada "lurdinha".', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 123, culture: 'Banana', topic: 'Manejo Cultural e Nutrição', text: 'O sistema de condução recomendado para a touceira de bananeira é manter três gerações simultâneas: "mãe", "filha" e "neta".', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 124, culture: 'Banana', topic: 'Manejo Cultural e Nutrição', text: 'A eliminação do coração da bananeira é uma prática que reduz o peso dos frutos e aumenta a incidência de pragas.', answer: 'F', explanation: 'É o contrário: a eliminação do coração aumenta o peso dos frutos e reduz a incidência de algumas pragas.' },
  { id: 125, culture: 'Banana', topic: 'Manejo Cultural e Nutrição', text: 'A ordem de exigência de macronutrientes pela bananeira é: potássio > nitrogênio > cálcio > magnésio > enxofre > fósforo.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 126, culture: 'Banana', topic: 'Manejo Cultural e Nutrição', text: 'O "azul da bananeira" é um sintoma de deficiência de magnésio, causado por excesso de potássio no solo.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 127, culture: 'Banana', topic: 'Manejo Cultural e Nutrição', text: 'O corte do pseudocaule após a colheita deve ser feito rente ao solo, e os restos devem ser removidos do bananal para não atrair pragas.', answer: 'F', explanation: 'O corte é feito a 30-50 cm do solo, e os restos ficam nas entrelinhas como cobertura/adubação — não são removidos.' },
  { id: 128, culture: 'Banana', topic: 'Doenças e Pragas', text: 'A sigatoka negra já está confirmada e amplamente disseminada em todos os estados do Nordeste brasileiro.', answer: 'F', explanation: 'Segundo a fonte, a sigatoka negra ainda não havia sido confirmada nos estados do Nordeste (situação de quarentena).' },
  { id: 129, culture: 'Banana', topic: 'Doenças e Pragas', text: 'O mal-do-Panamá, causado por Fusarium oxysporum f. sp. cubense, sobrevive no solo por mais de 20 anos, não havendo cura para plantas infectadas.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 130, culture: 'Banana', topic: 'Doenças e Pragas', text: 'A antracnose é considerada a principal doença de pós-colheita da banana, podendo permanecer quiescente em frutos verdes até a maturação.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 131, culture: 'Banana', topic: 'Doenças e Pragas', text: 'A broca-do-rizoma (Cosmopolites sordidus) é considerada a praga mais séria da bananeira, podendo causar perdas de até 100% nas variedades do tipo Comprida.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 132, culture: 'Banana', topic: 'Doenças e Pragas', text: 'O tratamento térmico de mudas contra a broca-do-rizoma consiste na imersão em água quente a 30°C por 2 horas.', answer: 'F', explanation: 'O tratamento correto é água quente a 54°C por 20 minutos, não 30°C por 2 horas.' },
  { id: 133, culture: 'Banana', topic: 'Colheita e Pós-Colheita', text: 'A banana deve ser colhida completamente madura, já que se trata de um fruto não climatérico.', answer: 'F', explanation: 'A banana é fruto climatérico — deve ser colhida verde.' },
  { id: 134, culture: 'Banana', topic: 'Colheita e Pós-Colheita', text: 'Na classificação da banana tipo Prata/Pacovan, frutos com mais de 16 cm de comprimento são considerados do tipo exportação.', answer: 'V', explanation: 'Afirmação correta.' },
  { id: 135, culture: 'Banana', topic: 'Colheita e Pós-Colheita', text: 'Na climatização da banana com etileno, a dose recomendada é de 0,1% (28 litros para cada 28 m³ de câmara), mantendo-a hermeticamente fechada nas primeiras 24 horas.', answer: 'V', explanation: 'Afirmação correta.' },

  // QUESTÕES EXTRAS EXTRAÍDAS DAS PROVAS ANTIGAS
  { id: 136, culture: 'Manga', topic: 'Prova Antiga - Fisiologia e Poda', text: 'Os ramos da mangueira com 10 a 24 meses de idade estão aptos a florescer em condições tropicais.', answer: 'F', explanation: 'Em condições tropicais (como o Semiárido nordestino), os ramos aptos a florescer têm de 4 a 18 meses de idade.' },
  { id: 137, culture: 'Manga', topic: 'Prova Antiga - Polinização', text: 'A baixa produção de frutos na mangueira causada pela baixa polinização pode estar ligada a baixa população de insetos visitantes florais durante a floração, a presença de outras espécies vegetais mais atrativas e as condições ambientais não favoráveis.', answer: 'V', explanation: 'A mangueira tem naturalmente baixa eficiência de polinização, o que é agravado por falta de insetos polinizadores e clima adverso.' },
  { id: 138, culture: 'Manga', topic: 'Prova Antiga - Poda', text: 'Na poda de formação das mangueiras de um pomar comercial a planta deverá ser conduzida em haste única após o plantio e ao atingir 0,80 a 1,0 m de altura será podada a 0,4 - 0,6 m. Em seguida selecionam-se três a quatro pernadas e para cada ramo escolhem-se três brotações.', answer: 'V', explanation: 'Essa é a recomendação padrão de poda de formação em haste única e quebra da dominância apical para formar a copa.' },
  { id: 139, culture: 'Manga', topic: 'Prova Antiga - Indução Floral', text: 'O paclobutrazol (PBZ) apresenta maior eficiência quando pulverizado na copa da mangueira na concentração de um grama por metro linear de copa.', answer: 'F', explanation: 'O paclobutrazol (PBZ) é aplicado via solo (via água de irrigação ou drench no colo da planta), e não pulverizado nas folhas da copa.' },
  { id: 140, culture: 'Geral', topic: 'Prova Antiga - Implantação de Pomar', text: 'Na abertura da cova de plantio o solo do horizonte "A" deve ser colocado de um lado da cova e o do horizonte "B" do outro. O adubo orgânico, químico e calagem deverá ser misturado ao horizonte "B" que será devolvido primeiro a cova, e posteriormente o "A".', answer: 'F', explanation: 'A mistura de adubos deve ser feita no solo do horizonte "A" (que já é naturalmente mais fértil), e é esse horizonte que vai para o fundo da cova primeiro.' },
  { id: 141, culture: 'Abacaxi', topic: 'Prova Antiga - Cultivares', text: 'A variedade de abacaxi Pérola mostra-se resistente à fusariose, sem espinhos e com muitos filhotes.', answer: 'F', explanation: 'A cultivar Pérola é altamente suscetível à fusariose e possui folhas com margens espinhosas.' },
  { id: 142, culture: 'Abacaxi', topic: 'Prova Antiga - Nutrição e Manejo', text: 'Na roseta foliar do abacaxizeiro não deve cair terra para não comprometer a gema apical, entretanto é permitido colocar adubos diretamente em seu interior.', answer: 'F', explanation: 'Não se deve jogar adubos sólidos descuidadamente dentro da roseta (olho) da planta, pois a alta concentração de sais queima as folhas jovens e pode matar a gema apical.' },
  { id: 143, culture: 'Abacaxi', topic: 'Prova Antiga - Fotoperíodo', text: 'Um fotoperíodo de 12 horas de luz influencia diretamente na floração natural do abacaxizeiro.', answer: 'V', explanation: 'Dias curtos estimulam o fechamento do ciclo vegetativo e a diferenciação floral no abacaxizeiro.' },
  { id: 144, culture: 'Abacaxi', topic: 'Prova Antiga - Propagação', text: 'A propagação rápida por seccionamento do caule do abacaxizeiro visa melhorar a sanidade em relação a fusariose principalmente, e aumentar o número de mudas.', answer: 'V', explanation: 'O fracionamento (secionamento) do caule acelera a produção de mudas sadias (livres de fusariose) sob ambiente controlado.' },
  { id: 145, culture: 'Abacaxi', topic: 'Prova Antiga - Fitossanidade', text: 'A fase mais crítica do abacaxizeiro é o período da floração onde a planta está mais vulnerável ao ataque da broca do fruto e entrada da fusariose.', answer: 'F', explanation: 'Embora a broca ataque nas flores abertas, a fusariose entra frequentemente muito antes (pelas mudas ou ferimentos). A afirmação mistura as dinâmicas e foi considerada falsa na prova.' },
  { id: 146, culture: 'Abacaxi', topic: 'Prova Antiga - Plantio', text: 'As mudas do tipo filhote são as mais usadas no Brasil para plantio de abacaxizeiro.', answer: 'V', explanation: 'As mudas tipo filhote são as preferidas comercialmente pois garantem excelente vigor e alta uniformidade no campo.' },
  { id: 147, culture: 'Abacaxi', topic: 'Prova Antiga - Soca', text: 'O ciclo da soca (segundo ciclo) do abacaxizeiro dura exatamente 12 meses.', answer: 'F', explanation: 'A duração do ciclo da soca é variável dependendo da época de colheita, do clima e do manejo da indução, não sendo fixa em 12 meses.' },
  { id: 148, culture: 'Abacaxi', topic: 'Prova Antiga - Soca', text: 'As mudas do tipo filhote e rebentão, se mantidas na planta mãe, poderão passar por um ciclo produtivo chamado de soca ou segundo ciclo.', answer: 'V', explanation: 'Exato. É assim que a soca é formada: aproveitando os brotos que permanecem na planta após a colheita do fruto principal.' },
  { id: 149, culture: 'Abacaxi', topic: 'Prova Antiga - Exigências Hídricas', text: 'Dadas as suas características de planta xerófita, o abacaxizeiro não precisa de chuvas mensais superiores a 40 mm para um crescimento vegetativo adequado e produção de frutos.', answer: 'F', explanation: 'Apesar de ter metabolismo CAM e resistir à seca, o abacaxizeiro comercial exige muito mais água (por chuvas regulares ou irrigação) para garantir frutos de bom tamanho e produtividade.' },
  { id: 150, culture: 'Abacaxi', topic: 'Prova Antiga - Plantio', text: 'A cultivar Pérola permite a utilização de espaçamentos menores que a cultivar Smooth Cayenne.', answer: 'F', explanation: 'É o contrário. Por possuir folhas mais longas e com muitos espinhos, a cultivar Pérola exige espaçamentos maiores do que a Smooth Cayenne.' },
  { id: 151, culture: 'Abacaxi', topic: 'Prova Antiga - Plantio', text: 'A escolha do sistema de plantio para a cultura do abacaxi depende muito mais de questões de manejo e operacionais do que de vantagens comparativas quanto a aspectos quantitativos e qualitativos da produção.', answer: 'F', explanation: 'A escolha do sistema de plantio afeta diretamente o rendimento, o controle de ervas daninhas, a proteção contra insolação dos frutos e as perdas, impactando muito a qualidade e a quantidade produzida.' },
  { id: 152, culture: 'Abacaxi', topic: 'Prova Antiga - Soca', text: 'A produtividade da soca do abacaxizeiro tende a ser inferior àquela do primeiro ciclo, devido a perdas de frutos por tombamento de plantas e produção de frutos com peso médio inferior.', answer: 'V', explanation: 'Frutos da soca tendem a ser menores, e os rebentões fixos na planta-mãe já degradada tombam com o peso, reduzindo o rendimento final.' },
  { id: 153, culture: 'Geral', topic: 'Prova Antiga - Reguladores', text: 'Paclobutrazol, ethephon e carbureto de cálcio são produtos utilizados como reguladores de crescimento e indutores em cultivos de abacaxizeiros e mangueiras no Semiárido.', answer: 'V', explanation: 'O PBZ paralisa o crescimento vegetativo da manga, e o ethephon/carbureto liberam etileno/acetileno para induzir a floração no abacaxi e na manga.' },
  { id: 154, culture: 'Geral', topic: 'Prova Antiga - Implantação', text: 'No plantio de espécies frutíferas, as operações clássicas de preparo do terreno seguem a ordem de: Limpeza, calagem e aração, gradagem.', answer: 'V', explanation: 'Primeiro limpa-se a área, depois aplica-se o calcário que será incorporado em profundidade pela aração, e finaliza-se destorroando com a gradagem.' },
  { id: 155, culture: 'Mamão', topic: 'Prova Antiga - Genética', text: 'A proporção de plantas hermafroditas e femininas é de 2:1 no cruzamento entre plantas hermafroditas (M2m x M2m).', answer: 'V', explanation: 'Nesse cruzamento, 1/4 das sementes recebe o genótipo letal M2M2 e aborta. Das sementes viáveis que sobram, 2/3 são hermafroditas (M2m) e 1/3 são femininas (mm).' },
  { id: 156, culture: 'Mamão', topic: 'Prova Antiga - Genética', text: 'No cruzamento entre plantas masculinas e femininas a proporção na descendência é de 1 planta masculina para 1 feminina (1:1).', answer: 'V', explanation: 'O cruzamento M1m (masculina) x mm (feminina) resulta em 50% M1m (masculinas) e 50% mm (femininas).' },
  { id: 157, culture: 'Mamão', topic: 'Prova Antiga - Clima', text: 'O mamoeiro é uma planta tipicamente tropical exigindo alta insolação, mas sua produção fica estritamente limitada a locais com temperatura cravada entre 22 e 26°C.', answer: 'F', explanation: 'Embora tropical, ele não é limitado a uma faixa tão estreita. Na verdade, temperaturas muito altas também causam problemas, mas o cultivo ocorre em gamas mais amplas.' },
  { id: 158, culture: 'Mamão', topic: 'Prova Antiga - Flores', text: 'As flores femininas são as mais importantes no pomar por gerar frutos de maior tamanho e formato arredondado.', answer: 'F', explanation: 'As flores mais importantes comercialmente são as HERMAFRODITAS do tipo elongata, que produzem o fruto alongado/piriforme (com maior cavidade interna e valor de mercado).' },
  { id: 159, culture: 'Mamão', topic: 'Prova Antiga - Flores', text: 'Frutos carpeloides são frutos deformados devido à supressão do desenvolvimento dos carpelos em vários graus.', answer: 'F', explanation: 'Ao contrário da supressão, a carpeloidia é a transformação errônea de estames em carpelos.' },
  { id: 160, culture: 'Mamão', topic: 'Prova Antiga - Sexagem', text: 'A sexagem das mudas consiste no desbaste por ocasião da floração, deixando-se apenas a planta de flor feminina em cada cova.', answer: 'F', explanation: 'O objetivo da sexagem é eliminar as plantas femininas e deixar apenas a planta de flor HERMAFRODITA.' },
  { id: 161, culture: 'Mamão', topic: 'Prova Antiga - Desbaste', text: 'O desbaste de frutos do mamoeiro tem objetivo de eliminar frutos defeituosos e pequenos, deixando-se um ou dois frutos por axila foliar.', answer: 'V', explanation: 'O desbaste evita que os frutos fiquem espremidos ("encavalados") e os padroniza para o mercado.' },
  { id: 162, culture: 'Mamão', topic: 'Prova Antiga - Botânica', text: 'O mamoeiro é uma planta estritamente monoica, apresentando flores masculinas e femininas separadas, além de plantas hermafroditas.', answer: 'F', explanation: 'O mamoeiro é uma espécie poligâmica/trioica. Existem plantas exclusivamente femininas, plantas exclusivamente masculinas (dióicas) e plantas hermafroditas.' },
  { id: 163, culture: 'Mamão', topic: 'Prova Antiga - Cultivares', text: 'As cultivares de mamão são divididas em Solo e Formosa, sendo o grupo Formosa geneticamente uniforme e capaz de ser propagado a partir de sementes colhidas no próprio pomar.', answer: 'F', explanation: 'O grupo Formosa é composto primariamente por híbridos. Sementes retiradas de frutos híbridos não devem ser replantadas, pois gerarão plantas desuniformes (segregação genética).' },
  { id: 164, culture: 'Mamão', topic: 'Prova Antiga - Fitopatologia', text: 'A deficiência de cálcio causa o surgimento de frutos encaroçados e malformados. Já o vírus da meleira causa a exsudação de látex mais fluído que escurece a casca.', answer: 'F', explanation: 'A afirmação mistura os conceitos. Frutos encaroçados são sintomas de deficiência de BORO, não de cálcio.' }
];
